-- PT113-S2-Q11. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT113-S2-Q11$batch06$ AND q.stimulus=$batch06$Mark: To convey an understanding of past events, a historian should try to capture what it was like to experience those events. For instance, a foot soldier in the Battle of Waterloo knew through direct experience what the battle was like, and it is this kind of knowledge that the historian must capture.
Carla: But how do you go about choosing whose perspective is the valid one? Is the foot soldier's perspective more valid than that of a general? Should it be a French or an English soldier? Your approach would generate a biased version of history, and to avoid that, historians must stick to general and objective characterizations of the past.$batch06$ AND q.prompt=$batch06$Mark's and Carla's positions indicate that they disagree about the truth of which one of the following?$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT113-S2-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT113-S2-Q11$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S2-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT113-S2-Q11$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Mark's Position$batch06$, $batch06$Historians should try to capture what it was like to experience past events, the way a foot soldier knew the battle.$batch06$), (1, $batch06$Carla's Position$batch06$, $batch06$Choosing one participant's view would bias history, so historians must stick to general, objective accounts.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Mark recommends the participant's-eye view. Carla rejects it in favor of the general, objective view. That is a direct "should" clash about how history ought to be written.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether historians should convey events from participants' perspectives.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT113-S2-Q11$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Neither disputes the purpose of history. Carla's objection is about method, not purpose.$batch06$), ($batch06$B$batch06$, $batch06$This is the most popular wrong answer. But neither speaker says whether participants understand events *objectively*. Mark talks about direct experience, and Carla about the historian's bias.$batch06$), ($batch06$C$batch06$, $batch06$Carla does not say historians *cannot* convey a participant's view, only that they should not.$batch06$), ($batch06$D$batch06$, $batch06$Mark says historians should capture the participant's experience. Carla says they should stick to general characterizations.$batch06$), ($batch06$E$batch06$, $batch06$Fiction never comes up.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT113-S2-Q11$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
